   package com.android.tools.lint.checks;

   import com.android.tools.lint.detector.api.*;
   import org.w3c.dom.Element;
   import org.w3c.dom.Node;
   import java.util.Collection;
   import java.util.Collections;

   public class InefficientWeightDetector extends Detector implements XmlScanner {
       public static final Issue ISSUE = Issue.create(
           "NestedWeights",
           "Nested layout weights",
           "Layout weights require a widget to be measured twice. When a LinearLayout with " +
           "non-zero weights is nested inside another LinearLayout with non-zero weights, " +
           "then the number of measurements increase exponentially.",
           Category.PERFORMANCE,
           3,
           Severity.WARNING,
           new Implementation(InefficientWeightDetector.class, Scope.RESOURCE_FILE_SCOPE)
       );

       @Override
       public Collection<String> getApplicableElements() {
           return Collections.singletonList("LinearLayout");
       }

       @Override
       public void visitElement(XmlContext context, Element element) {
           // Check if this LinearLayout has a non-zero layout_weight
           if (hasNonZeroWeight(element)) {
               // Check ancestors for LinearLayout with non-zero weight
               Node parent = element.getParentNode();
               while (parent != null) {
                   if (parent.getNodeType() == Node.ELEMENT_NODE) {
                       Element parentElement = (Element) parent;
                       if ("LinearLayout".equals(parentElement.getTagName()) && hasNonZeroWeight(parentElement)) {
                           // Found nested weight
                           String weightValue = element.getAttributeNS(SdkConstants.ANDROID_URI, "layout_weight");
                           context.report(ISSUE, element, context.getLocation(element.getAttributeNodeNS(SdkConstants.ANDROID_URI, "layout_weight")),
                               "Nested weights are bad for performance");
                           return; // Only report once per element
                       }
                   }
                   parent = parent.getParentNode();
               }
           }
       }

       private boolean hasNonZeroWeight(Element element) {
           String weightStr = element.getAttributeNS(SdkConstants.ANDROID_URI, "layout_weight");
           if (weightStr != null && !weightStr.isEmpty()) {
               try {
                   float weight = Float.parseFloat(weightStr);
                   return weight > 0.0f;
               } catch (NumberFormatException e) {
                   // Ignore invalid values
               }
           }
           return false;
       }
   }
   ```

