import java.util.Collection;
import java.util.Collections;

public class InefficientWeightDetector extends Detector implements XmlScanner {

    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";
    private static final String ATTR_LAYOUT_WEIGHT = "layout_weight";
    private static final String TAG_LINEAR_LAYOUT = "LinearLayout";

    public static final Issue ISSUE = Issue.create(
            "NestedWeights",
            "Nested layout weights",
            "Layout weights require a widget to be measured twice. When a LinearLayout with " +
            "non-zero weights is nested inside another LinearLayout with non-zero weights, " +
            "then the number of measurements increase exponentially.",
            Category.PERFORMANCE,
            3,
            Severity.WARNING,
            new Implementation(InefficientWeightDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_LINEAR_LAYOUT);
    }

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        Attr weightAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weightAttr == null) {
            return;
        }

        String weightStr = weightAttr.getValue();
        if (weightStr == null || weightStr.isEmpty()) {
            return;
        }

        try {
            float weight = Float.parseFloat(weightStr.trim());
            if (weight > 0.0f) {
                // This LinearLayout has a weight. Check if it has any children with weights.
                for (Node child = element.getFirstChild(); child != null; child = child.getNextSibling()) {
                    if (child.getNodeType() == Node.ELEMENT_NODE) {
                        Element childEl = (Element) child;
                        Attr childWeightAttr = childEl.getAttributeNodeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
                        if (childWeightAttr != null) {
                            String childWeightStr = childWeightAttr.getValue();
                            if (childWeightStr != null && !childWeightStr.isEmpty()) {
                                float childWeight = Float.parseFloat(childWeightStr.trim());
                                if (childWeight > 0.0f) {
                                    context.report(ISSUE, context.getLocation(weightAttr),
                                            "Nested weights are bad for performance");
                                    return;
                                }
                            }
                        }
                    }
                }
            }
        } catch (NumberFormatException ignored) {
            // Ignore non-numeric weights
        }
    }
}
